content:
.auth-root {
    display: flex;
    justify-content: center;
    margin: 4rem 0;
}

.auth-wrapper {
    background: white;
    height: 280px;
    width: 450px;
    position: relative;
    z-index: 1;
    box-shadow: 1px 1px 10px gray;
    border-radius: 15px;
}

@media (prefers-color-scheme: dark) {
    .auth-wrapper {
        background: #2e2e34;
        box-shadow: 1px 1px 10px #494949;
    }
}

.makeElementMiddle {
    position: absolute;
    top: 50%;
    left: 50%;
    transform: translate3D(-50%, -50%, 0)
}

.authBox input {
    display: block;
    width: 300px;
    height: 40px;
    outline: none;
    border: none;
    border-radius: 1px
}

.hexo-auth-string {
    transition: 1s;
}

.hexo-auth-string.red {
    animation: shake .3s ease-in-out;
}

@keyframes shake {
    0% {
        transform: translateX(0);
    }

    12% {
        transform: translateX(-1rem);
    }

    36% {
        transform: translateX(1rem);
    }

    50% {
        transform: translateX(0);
    }

    62% {
        transform: translateX(-1rem);
    }

    86% {
        transform: translateX(1rem);
    }

    100% {
        transform: translateX(0);
    }
}


.input input {
    text-indent: 1em;
    font-size: .8em
}

.btn {
    margin-top: 20px
}

.greenBtn {
    margin: 7px 0;
    color: white;
    opacity: .8;
    border-radius: 2px;
    cursor: pointer
}

.greenBtn {
    background: #23ad4f
}

.btn input:hover {
    opacity: 1
}

.auth-root h1.article-title {
    display: inline-flex;
    align-items: center;
    position: relative;
    top: -1rem;
    height: 2rem;
    color: #696969;
    margin-left: 0;
    font-weight: 300;
    line-height: 35px;
    margin-bottom: 20px;
    font-size: 26px;
    transition: color .3s;
    margin-bottom: 10px;
}


.HEP-SVG {
    width: 200px;
    height: 200px;
    margin: 2.5rem auto;
}

.HEP-SVG.unlock-icon {
    display: none;
}

.HEP-SVG.lock-icon {
    width: 2rem;
    height: 2rem;
    margin-right: .3rem;
}

.HEP-SVG path,
.HEP-SVG circle,
.HEP-SVG rect {
    stroke: #23ad4f;
    stroke-width: 1;
    stroke-linecap: round;
    fill: none;
    stroke-dasharray: 70;
}

.HEP-SVG.lock-icon path,
.HEP-SVG.lock-icon circle,
.HEP-SVG.lock-icon rect {
    stroke: darkgray;
}

.HEP-SVG.unlock-icon path,
.HEP-SVG.unlock-icon circle,
.HEP-SVG.unlock-icon rect {
    stroke-dashoffset: 70;
    animation: unlock 1s ease-in-out forwards;
}

@keyframes unlock {
    0% {
        stroke-dashoffset: 70;
    }

    100% {
        stroke-dashoffset: 0;
    }
}















