async function unlock_36pz14_xhwMWU_7ea22f(event) {

    function errorHint(passwordInput, msg) {
        passwordInput.classList.add('red')
        passwordInput.value = ''
        passwordInput.placeholder = msg
        setTimeout(() => {
            passwordInput.classList.remove('red')
        }, 1000)
    }

    const target = event.target
    const root = target.parentElement.parentElement.parentElement.parentElement.parentElement

    const passwordInput = root.querySelector('.hexo-auth-string')
    if (!passwordInput || !passwordInput.value) return
    const password = passwordInput.value
    let content = ''
    let isMatch = false

    let titleElement = root.nextElementSibling.nextElementSibling
    let _title = ''
    try {
        let keys = await fetch('/@encrypted/encrypted.json')
        let ivs = await fetch('/@encrypted/encrypted2.json')
        if (!titleElement) throw new Error('找不到容器 Abort')
        content = titleElement.textContent.trim()
        _title = titleElement.getAttribute('title')
        if (!content || !_title) throw new Error('找不到加密数据或者标题 Abort')
        keys = await keys.json()
        ivs = await ivs.json()
        let _key = keys[_title]
        let _iv = ivs[_title]
        if (!_key || !_iv) throw new Error('找不到盐 Abort')
        _key = (password + _key).slice(0, 32)
        _iv = (_iv + password).split("").reverse().join("").slice(0, 16)
        let authString = aesjs.utils.utf8.toBytes(_key)
        const iv = aesjs.utils.utf8.toBytes(_iv)
        const aesCbc = new aesjs.ModeOfOperation.cbc(authString, iv)
        const encryptedBytes = aesjs.utils.hex.toBytes(content)
        const decryptedBytes = aesCbc.decrypt(encryptedBytes)
        const value = aesjs.utils.utf8.fromBytes(decryptedBytes)
        content = value.trim()
        authString = new TextDecoder().decode(authString)
        if (content && content.slice(0, 32) === authString) {
            content = content.slice(32)
            titleElement.innerHTML = content
            isMatch = true
        }
    } catch (e) {
        console.error(e)
        errorHint(passwordInput, '无法获取数据，请尝试[$: hexo clean & hexo g]')
        throw e
    }


    if (isMatch) {
        root.querySelector('.makeElementMiddle').remove()
        const icon = root.querySelector('svg.unlock-icon')
        icon.style.display = 'block'
        setTimeout(() => {
            root.remove()
            titleElement.style.display = 'block'
        }, 1000)
        localStorage.setItem(_title, password)
    } else {
        errorHint(passwordInput, '解锁码不正确')
    }
}

