    const passwordInput = root.querySelector('.hexo-auth-string')

    const _i = setInterval(() => {
        let titleElement = root.nextElementSibling.nextElementSibling
        if (titleElement) {
            clearInterval(_i)
            const _title = titleElement.getAttribute('title')
            const password = localStorage.getItem(_title)
            if (password) {
                passwordInput.value = password
                const btn = root.querySelector('.btn input')
                if (btn) btn.click()
            }
        }
